```go
func main() {
    odd, even := make(chan struct{}), make(chan struct{})
    var wg sync.WaitGroup
    wg.Add(2)

    go func() {
        defer wg.Done()
        for i := 1; i <= 10; i += 2 {
            <-odd // 等待轮到自己
            fmt.Println(i)
            even <- struct{}{} // 交给偶数协程
        }
    }()

    go func() {
        defer wg.Done()
        for i := 2; i <= 10; i += 2 {
            <-even
            fmt.Println(i)
            if i < 10 { // 最后一次不再通知，否则会因为没有接收者而永久阻塞
                odd <- struct{}{}
            }
        }
    }()

    odd <- struct{}{} // 从奇数开始
    wg.Wait()
}
```

**扩展：N 个 goroutine 按顺序循环打印 A、B、C**，每个 goroutine 等待自己的 channel，打印后通知下一个：

```go
func PrintInOrder(names []string, rounds int) {
    chs := make([]chan struct{}, len(names))
    for i := range chs {
        chs[i] = make(chan struct{}, 1)
    }
    var wg sync.WaitGroup
    for i, name := range names {
        wg.Add(1)
        go func() {
            defer wg.Done()
            for range rounds {
                <-chs[i]
                fmt.Print(name)
                chs[(i+1)%len(chs)] <- struct{}{} // 缓冲为 1，最后一次通知也不会阻塞
            }
        }()
    }
    chs[0] <- struct{}{}
    wg.Wait()
}
```

注意最后一轮的通知：没有接收者时会永久阻塞。解决办法是使用缓冲为 1 的 channel，或者像第一个例子那样跳过最后一次通知。

```go
type Pool struct {
    tasks chan func()
    wg    sync.WaitGroup
    once  sync.Once
}

func NewPool(workers, queueSize int) *Pool {
    p := &Pool{tasks: make(chan func(), queueSize)}
    p.wg.Add(workers)
    for range workers {
        go p.worker()
    }
    return p
}

func (p *Pool) worker() {
    defer p.wg.Done()
    for task := range p.tasks { // channel 关闭且任务取完后退出
        p.run(task)
    }
}

func (p *Pool) run(task func()) {
    defer func() {
        if r := recover(); r != nil { // 单个任务 panic 不能让 worker 退出，更不能让进程崩溃
            slog.Error("task panic", "err", r, "stack", string(debug.Stack()))
        }
    }()
    task()
}

// Submit 在队列满时阻塞，直到有空位或者 ctx 被取消
func (p *Pool) Submit(ctx context.Context, task func()) error {
    select {
    case p.tasks <- task:
        return nil
    case <-ctx.Done():
        return ctx.Err()
    }
}

// Close 停止接收新任务，并等待已经提交的任务全部执行完毕
func (p *Pool) Close() {
    p.once.Do(func() { close(p.tasks) })
    p.wg.Wait()
}
```

设计取舍：

-   队列满时是阻塞、直接拒绝，还是丢弃最旧的任务？这里选择阻塞，并通过 ctx 控制等待时间；
-   `Close` 之后再调用 `Submit` 会向已关闭的 channel 发送数据而 panic。生产环境中需要加一个关闭标志，用 RWMutex 保护 Submit 和 Close；
-   任务需要返回结果时，可以让任务本身写入结果 channel，或者直接使用 `errgroup.SetLimit`。

questions.deep:
**原理展开**

在 Go 中设计 Worker Pool（协程池）时，首先需要理解它与 Java/C++ 线程池的本质差异：Go 的 goroutine 创建开销极小（初始栈仅 2KB，分配耗时几百纳秒），在大多数常规 I/O 场景下直接 `go fn()` 配合信号量（`errgroup.SetLimit`）就足够了。Worker Pool 真正的工程价值在于**限制峰值并发资源消耗（CPU/内存/下游连接）**以及**提供明确的背压（Backpressure）与队列排队策略**。

实现一个生产级 Worker Pool 最大的难点是：**如何安全地解决 `Submit` 与 `Close` 之间的并发竞态**？
在基础版代码中，如果协程 A 正在调用 `Submit(task)`，而协程 B 同时调用了 `Close()` 执行 `close(p.tasks)`，协程 A 就会向已关闭的 channel 发送数据，直接触发运行时无法容忍的 **`panic: send on closed channel`**！要彻底消除这个竞态，必须保证“检查未关闭并发送任务”与“标记关闭并 `close(ch)`”是互斥的。

**代码示例**

```go
// 并发安全的生产级 Pool：使用 RWMutex 消除 Submit 与 Close 的关门竞态，哪怕并发混调也绝不 panic
var ErrPoolClosed = errors.New("worker pool is closed")

type SafePool struct {
	mu     sync.RWMutex
	closed bool
	tasks  chan func()
	wg     sync.WaitGroup
}

func NewSafePool(workers, queueSize int) *SafePool {
	p := &SafePool{tasks: make(chan func(), queueSize)}
	p.wg.Add(workers)
	for range workers {
		go func() {
			defer p.wg.Done()
			for task := range p.tasks {
				task()
			}
		}()
	}
	return p
}

func (p *SafePool) Submit(ctx context.Context, task func()) error {
	// 持有读锁：允许多个 Submit 并发进行，但阻止 Close 在此时关闭 channel
	p.mu.RLock()
	defer p.mu.RUnlock()
	if p.closed {
		return ErrPoolClosed
	}
	select {
	case p.tasks <- task:
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

func (p *SafePool) Close() {
	// 获取写锁：等待所有正在尝试发送的 Submit 退出后，才标记 closed 并安全关闭 channel
	p.mu.Lock()
	if !p.closed {
		p.closed = true
		close(p.tasks)
	}
	p.mu.Unlock()
	p.wg.Wait() // 在锁外等待已有任务排空完成，避免死锁
}
```

**常见追问**

- 在上面的 `SafePool` 中，如果队列满了，某个 `Submit` 拿着读锁 `RLock()` 阻塞在 `select` 等待空位，此时另一个协程调用 `Close()` 尝试拿写锁 `Lock()` 会发生什么？→ 如果所有 worker 还在正常消费队列，队列很快腾出空位，`Submit` 写入成功并释放读锁，`Close()` 顺利拿到写锁；但如果某个正在运行的 task 内部又递归调用了同一个 Pool 的 `Submit`，且队列已满，就会发生**自死锁（Pool Deadlock）**！因此严禁向同一个固定容量的同步协程池提交相互等待的父子任务。
- 队列满时的四种背压策略分别适用什么场景？→ ① **阻塞等待（Block with Context）**：适合普通异步任务；② **立即拒绝（Fail-Fast，用 `select + default`）**：适合高并发网关快速降级；③ **调用者自执行（Caller-Runs）**：由当前调用 `Submit` 的协程自己同步把 `task()` 跑完，自然减慢上游生产速度；④ **丢弃最旧任务（Drop-Oldest）**：适合实时监控指标或行情推送。
- 开源的高性能协程池（如 `panjf2000/ants`）相比固定 channel 的实现做了什么优化？→ 它不让所有 worker 争抢同一个全局 `chan func()`（高并发下全局 channel 内部的 `hchan.lock` 会成为瓶颈），而是维护一个空闲 worker 栈/队列（每个 worker 绑定自己独享的容量为 1 的 channel），实现 LIFO 局部性唤醒和按空闲超时动态缩容。

**实战建议**

- 如果业务只是在一个函数内并发跑一批任务并等待全部结束，**优先使用 `errgroup.Group` + `SetLimit(n)`**，代码量少且不需要维护 Pool 的生命周期。
- 任何常驻后台的 Worker 协程都必须在 `run(task)` 外层包一层 `defer recover()` 并打印调用栈，防止某条脏数据触发空指针直接把整个进程搞挂。

